mod solver;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng,ic::{solve_dlp,IcParams},solve::Solver};
fn main(){let old=include_str!("../native-public-2lp/CONTROL.txt");let mut calls=0;let mut failures=0;
 for line in include_str!("INSTANCES.tsv").lines().skip(1){counted::disable();let v:Vec<_>=line.split('\t').collect();let g:usize=v[0].parse().unwrap();let p:u64=v[1].parse().unwrap();let cc:u64=v[2].parse().unwrap();let ell:u64=v[3].parse().unwrap();let inst=pick_instance(p,g).unwrap();assert_eq!(inst.c,cc);assert_eq!(inst.ell,ell);assert_eq!(inst.curve.f.c[..inst.curve.f.n].iter().map(u64::to_string).collect::<Vec<_>>().join(","),v[4]);let mut rng=Rng::new(2026111800^p^((g as u64)<<32));
 for case in 0..2{let sm=if case==0{1}else{17};let d=inst.curve.mul(&inst.d1,sm);let k=1+rng.below(ell-1);let t=inst.curve.mul(&d,k);let seed=2026111800+case as u64;let prefix=format!("CASE g={g} p={p} c={cc} ell={ell} source_multiple={sm} case={case} seed={seed} expected={k} ");let receipt=old.lines().find(|l|l.starts_with(&prefix)).unwrap();
 let mut prior=std::collections::BTreeMap::new();for rep in 0..2{let order=if(case+rep)%2==0{[0,1,2,3]}else{[3,2,1,0]};for arm in order{let name=["2lp","full_fast","full_dense","full_hybrid"][arm];eprintln!("start g={g} p={p} case={case} arm={name} rep={rep}");counted::reset();
 let(answer,trials,rows,pivots)=if arm==0{let r=solver::solve(&inst.curve,&d,&t,ell,&solver::Params{seed,limit:200000,audit_prefix:0});assert_eq!(r.audits,0);(r.k,r.trials,r.full_rows,r.pivots)}else{solver::validate(&inst.curve,&d,&t,ell);let mode=match arm{1=>Solver::Fast,2=>Solver::Dense,_=>Solver::Hybrid};let r=solve_dlp(&inst.curve,&d,&t,ell,&IcParams{seed,max_trials:200000,solver:mode,reference_oracle:false,..IcParams::default()});(r.k,r.trials,r.relations as usize,0)};
 let counts=counted::snapshot();counted::disable();let correct=answer==Some(k);if !correct{failures+=1;}if let Some(answer)=answer{assert_eq!(answer,k);assert_eq!(inst.curve.mul(&d,answer),t);}if arm==0{for(field,value)in[("trials=",trials),("pivots=",pivots as u64),("full_rows=",rows as u64)]{assert_eq!(receipt.split_whitespace().find_map(|s|s.strip_prefix(field)).unwrap().parse::<u64>().unwrap(),value);}}if arm==1{assert_eq!(receipt.split_whitespace().find_map(|s|s.strip_prefix("fullbase_trials=")).unwrap().parse::<u64>().unwrap(),trials);}
 let signature=(answer,trials,rows,pivots,counts.clone());if let Some(old)=prior.get(&arm){assert_eq!(old,&signature);}else{prior.insert(arm,signature);}
 println!("OUTCOME g={g} p={p} c={cc} ell={ell} source_multiple={sm} case={case} arm={name} rep={rep} k={answer:?} trials={trials} rows={rows} lp_pivots={pivots} correct={correct}");for(modulus,values)in counts{assert_eq!(values[8],2*values[7]+values[5]+values[6]);println!("COUNT g={g} p={p} source_multiple={sm} case={case} arm={name} rep={rep} modulus={modulus} vector={values:?}");}calls+=1;
 }} }}assert_eq!(calls,176);eprintln!("SUMMARY original_models=11 fixtures=22 complete_calls={calls} failures={failures} matched_validation_paid_all_arms=true oracle_optimized_all_arms=true candidate_diagnostic_prefix_disabled=true outcomes_replay_prior_correctness=true repeats_exact=true field_count_identity=true no_wall_or_mixed_modulus_speed_claim=true");if failures>0{std::process::exit(2);}}
